from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.components.component_collection import ComponentCollection


class Fhgw(BtsComponent):
    """ Represents generic Fronthaul Gateway. """

    def __init__(self, parent):
        """
        :param parent: BTS component to which this FHGW is connected; usually it is DU
        """
        super(Fhgw, self).__init__('FHGW')
        self._parent = parent
        self._rmods = ComponentCollection()
